/// <summary>
/// Extension of RetailPricingSimulator
/// </summary>
[ExtensionOf(classStr(RetailPricingSimulator))]
final class METRetailPricingSimulator_Extension
{

}

Method.Source:
    /// <summary>
    /// CoC
    /// </summary>
    protected void updatePriceAndDiscountsInDbTable()
    {
        next updatePriceAndDiscountsInDbTable();

        this.metAddAdditionalDetail();  // MPJ-26540

    }

    /// <summary>
    /// MPJ-26540 Add charges to simulation header
    /// </summary>
    private void metAddAdditionalDetail()
    {
        RetailPricingSimulatorSalesLine metSimSalesLine;
        InventTable                     metInventTable;
        InventTableModule               metInventTableModuleInvent;
        CustTable                       metCustTable;
        date                            metToday = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());

        ttsbegin;

        //DCP 08/08/2022 Code cleanup
        while select forupdate METChargesAmount, METTaxAmountTotal, METUnitOfMeasureConversion, METTotalCharges, METTaxAmountPerUnit,
                                METLandedCostAmount, METTotalSalesPrice, METMarginPercent, METBaseInventoryCost, METTaxAmountLCExclusions, 
                                METTotalChargesTax, Product, Quantity, RetailPricingSimulatorSalesTransaction, SalesPrice, UoM, RecId
            from    metSimSalesLine
            where   metSimSalesLine.RetailPricingSimulatorSalesTransaction  == psSalesTransaction.RecID
        {
            metInventTable             = InventTable::findByProduct(metSimSalesLine.Product);
            metInventTableModuleInvent = metInventTable.inventTableModuleInvent();
            metCustTable               = CustTable::find(psSalesTransaction.CustAccount);
            
            this.metAddCharges(metSimSalesLine, metInventTable, metCustTable);
            this.metAddTax(metSimSalesLine, metInventTable, metCustTable);
            
            // UoM
            Qty metConversionToInvUnit;
            UnitOfMeasureConversion metUomConversion = UnitOfMeasureConversion::findByConversion(metSimSalesLine.UoM,
                                                                                                UnitOfMeasure::findBySymbol(metInventTableModuleInvent.UnitId).RecId,
                                                                                                metSimSalesLine.Product);
            
            if(metUomConversion)
            {
                metSimSalesLine.METUnitOfMeasureConversion = metUomConversion.displayQuickFormulaWithLocalSeparators();
                metConversionToInvUnit = metUomConversion.Factor;
            }

            // Summary/total fields
            Price metPricePerUnit = metSimSalesLine.SalesPrice / (metSimSalesLine.Quantity ? metSimSalesLine.Quantity : 1);

            metSimSalesLine.METTaxAmountTotal  += metSimSalesLine.METTotalChargesTax;
            metSimSalesLine.METTaxAmountPerUnit = metSimSalesLine.METTaxAmountTotal / (metSimSalesLine.Quantity ? metSimSalesLine.Quantity : 1);
                   
            metSimSalesLine.METLandedCostAmount = (metSimSalesLine.SalesPrice + metSimSalesLine.METTotalCharges + metSimSalesLine.METTaxAmountLCExclusions) / 
                                                (metSimSalesLine.Quantity ? metSimSalesLine.Quantity : 1) / 
                                                (metConversionToInvUnit ? metConversionToInvUnit : 1);
                
            metSimSalesLine.METTotalSalesPrice     = metSimSalesLine.SalesPrice + metSimSalesLine.METTotalCharges + metSimSalesLine.METTaxAmountTotal;
            
            metSimSalesLine.METBaseInventoryCost   = GUPItemBasePrice::findCurrent(metInventTable.ItemId,
                                                                                    GUPBasePriceType::BasePriceInventoryCost,
                                                                                    metSimSalesLine.InventDimId,
                                                                                    metToday).Price;
            
            if(metPricePerUnit + metSimSalesLine.METChargesAmount)
            {
                metSimSalesLine.METMarginPercent = (metPricePerUnit + metSimSalesLine.METChargesAmount - metSimSalesLine.METBaseInventoryCost) /
                                                    (metPricePerUnit + metSimSalesLine.METChargesAmount) * 100;
            }
            
            metSimSalesLine.update();
        }

        ttscommit;
    }

    /// <summary>
    /// Add tax calculation
    /// </summary>
    /// <param name = "_metSimSalesLine">Retail simulator Sales line</param>
    /// <param name = "_metInventTable">Inventory table</param>
    /// <param name = "_metCustTable">Customer table</param>
    private void metAddTax(RetailPricingSimulatorSalesLine _metSimSalesLine, InventTable _metInventTable, CustTable _metCustTable)
    {
        RetailPricingSimulatorSalesLine metSimSalesLine = _metSimSalesLine;
        CustTable                       metCustTable    = _metCustTable;
        InventTable                     metInventTable  = _metInventTable;
        InventTableModule               metInventTableModuleSales = metInventTable.inventTableModuleSales();
        Amount                          metTaxAmount;
        Tax                             metTax;
        TransDate                       metTaxDate = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());

        // All tax codees
        metTax = Tax::construct();
        metTaxAmount = metTax.taxCalcWithoutSource(metCustTable.TaxGroup,
                                                    metInventTableModuleSales.TaxItemGroupId,
                                                    metTaxDate,
                                                    psSalesTransaction.ChannelCurrency,
                                                    metSimSalesLine.SalesPrice,
                                                    TaxModuleType::Sales);

        metSimSalesLine.METTaxAmountTotal = metTaxAmount;
        
        // Calculation with landed cost tax code exclusions
        metTax = Tax::construct();
        metTax.parmMetExcludeBasedOnLandedCostCalcFlag(true);

        metTaxAmount = metTax.taxCalcWithoutSource(metCustTable.TaxGroup,
                                                    metInventTableModuleSales.TaxItemGroupId,
                                                    metTaxDate,
                                                    psSalesTransaction.ChannelCurrency,
                                                    metSimSalesLine.SalesPrice,
                                                    TaxModuleType::Sales);

        metSimSalesLine.METTaxAmountLCExclusions = metTaxAmount;
        
    }

    /// <summary>
    /// Add charges detail
    /// </summary>
    /// <param name = "_metSimSalesLine">Retail simulator Sales line</param>
    /// <param name = "_metInventTable">Inventory table</param>
    /// <param name = "_metCustTable">Customer table</param>
    private void metAddCharges(RetailPricingSimulatorSalesLine _metSimSalesLine, InventTable _metInventTable, CustTable _metCustTable)
    {
        RetailPricingSimulatorSalesLine         metSimSalesLine = _metSimSalesLine;
        CustTable                               metCustTable   = _metCustTable;
        InventTable                             metInventTable = _metInventTable;
        
        MarkupTrans                             metMarkupTrans;
        MarkupTable                             metMarkupTable;
        METRetailPricingSimulatorMarkupTrans    metSimMarkupTrans;
        TransDate                               metTaxDate = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());
        MarkupAmount                            metCalculatedAmount;

        delete_from metSimMarkupTrans
            where   metSimMarkupTrans.SimulatorSalesLine == metSimSalesLine.RecId;

        Markup::insertMarkupTrans(HeadingLine::Line,
                                    MarkupModuleType::Cust,
                                    psSalesTransaction,
                                    metCustTable.AccountNum,
                                    metCustTable.MarkupGroup,
                                    metCustTable.Currency,
                                    metCustTable.languageId(),
                                    metInventTable.ItemId);

        metSimSalesLine.METChargesAmount  = 0;
        metSimSalesLine.METTotalCharges   = 0;

        RecordInsertList metInsertList = new RecordInsertList(tableNum(METRetailPricingSimulatorMarkupTrans));

        while select metMarkupTrans        //leaving 'select all' as is. MarkupTrans record buffer used repeatedly in multiple method calls
            where   metMarkupTrans.TransTableId    == psSalesTransaction.TableID
            &&      metMarkupTrans.TransRecId      == psSalesTransaction.RecID
            
        join    TaxItemGroup
            from    metMarkupTable
            where   metMarkupTable.MarkupCode      == metMarkupTrans.MarkupCode
            &&      metMarkupTable.ModuleType      == MarkupModuleType::Cust
        {
            metCalculatedAmount = Markup::calcTrans(metMarkupTrans,
                                                    metSimSalesLine.Quantity,
                                                    metSimSalesLine.SalesPrice,
                                                    0,      // Intercompany price requirements?
                                                    metTaxDate);

            metSimMarkupTrans.clear();
            metSimMarkupTrans.SimulatorSalesTransaction    = psSalesTransaction.RecID;
            metSimMarkupTrans.SimulatorSalesLine           = metSimSalesLine.RecId;
            metSimMarkupTrans.MarkupCode                   = metMarkupTrans.MarkupCode;
            metSimMarkupTrans.MarkupCategory               = metMarkupTrans.MarkupCategory;
            metSimMarkupTrans.Value                        = metMarkupTrans.Value;
            metSimMarkupTrans.CalculatedAmount             = metCalculatedAmount;

            if(metSimMarkupTrans.MarkupCategory == MarkupCategory::Fixed)
            {
                metSimMarkupTrans.AmountPerUnit    = metSimMarkupTrans.CalculatedAmount;
            }
            else
            {
                metSimMarkupTrans.AmountPerUnit    = metSimMarkupTrans.CalculatedAmount / (metSimSalesLine.Quantity ? metSimSalesLine.Quantity : 1);
            }

            
            metSimMarkupTrans.TaxAmount = Tax::calcTaxAmount(metCustTable.TaxGroup,
                                                            metMarkupTable.TaxItemGroup,
                                                            metTaxDate,
                                                            psSalesTransaction.ChannelCurrency,
                                                            metSimMarkupTrans.CalculatedAmount,
                                                            TaxModuleType::Sales);

            metInsertList.add(metSimMarkupTrans);

            metSimSalesLine.METTotalCharges       += metSimMarkupTrans.CalculatedAmount;
            metSimSalesLine.METChargesAmount      += metSimMarkupTrans.AmountPerUnit;
            metSimSalesLine.METTotalChargesTax    += metSimMarkupTrans.TaxAmount;
        }
        metInsertList.insertDatabase();

        delete_from metMarkupTrans
            where   metMarkupTrans.TransTableId    == psSalesTransaction.TableID
            &&      metMarkupTrans.TransRecId      == psSalesTransaction.RecID;
    }
